import { generateKeyPairSync } from 'crypto';
import { spawnSync } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import ts from 'typescript';
import { verifyRegistrySignature } from '../../src/utils/registry-signature';

// Runs the signing scripts against a throwaway repo. Every key here is generated by the test (or by
// keygen in the throwaway repo) and only ever held in memory and the temp directory.
const REPO = path.join(__dirname, '../..');
const SCRIPTS = ['sign-registry.js', 'registry-keygen.js', 'registry-support.js', 'prepare-registry.js'];
const REGISTRY = 'src/extension-registry.json';
const SIGNATURE = 'src/extension-registry.json.sig';
const KEYS = 'src/registry-signing-keys.ts';
const SCHEMA = 'dist/utils/registry-schema.js';
const REGISTRY_TEXT = fs.readFileSync(path.join(REPO, REGISTRY), 'utf8');
const KEYS_DECLARATION = /(REGISTRY_SIGNING_KEYS: readonly string\[\] = )\[[^\]]*\]/;
// The committed key list, emptied: tests only ever list their own keys.
const KEYS_TEMPLATE = fs.readFileSync(path.join(REPO, KEYS), 'utf8').replace(KEYS_DECLARATION, '$1[]');
const support = require('../../scripts/registry-support');

let root: string;
const file = (rel: string) => path.join(root, rel);
const write = (rel: string, content: string) => {
  fs.mkdirSync(path.dirname(file(rel)), { recursive: true });
  fs.writeFileSync(file(rel), content);
};
const read = (rel: string) => fs.readFileSync(file(rel), 'utf8');
const writeKeys = (keys: string[], rel = KEYS) =>
  write(rel, KEYS_TEMPLATE.replace(KEYS_DECLARATION, `$1[\n${keys.map((key) => `  '${key}',\n`).join('')}]`));

/** A throwaway ed25519 key pair as raw hex, the format keygen prints and sign-registry reads. */
function testKey() {
  const { privateKey, publicKey } = generateKeyPairSync('ed25519');
  return {
    secret: privateKey.export({ format: 'der', type: 'pkcs8' }).subarray(16).toString('hex'),
    public: publicKey.export({ format: 'der', type: 'spki' }).subarray(12).toString('hex'),
  };
}

/** Runs a script in the throwaway repo with only PATH and `env`, so no real key can leak in. */
function run(script: string, args: string[] = [], env: Record<string, string> = {}) {
  const result = spawnSync(process.execPath, [file(`scripts/${script}`), ...args], {
    cwd: root,
    encoding: 'utf8',
    env: { PATH: process.env.PATH ?? '', ...env },
  });
  return { status: result.status, stdout: result.stdout, output: `${result.stdout}${result.stderr}` };
}
const sign = (secret: string, args: string[] = []) => run('sign-registry.js', args, { REGISTRY_SIGNING_KEY: secret });

function filesUnder(dir: string): string[] {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? filesUnder(full) : [full];
  });
}

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), 'registry-signature-'));
  for (const script of SCRIPTS) {
    write(`scripts/${script}`, fs.readFileSync(path.join(REPO, 'scripts', script), 'utf8'));
  }
  write(REGISTRY, REGISTRY_TEXT);
  writeKeys([]);
});

afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

// The scripts run on copies: the repo's own key list must never get a test key.
const COMMITTED_KEYS = fs.readFileSync(path.join(REPO, KEYS), 'utf8');
afterAll(() => expect(fs.readFileSync(path.join(REPO, KEYS), 'utf8')).toBe(COMMITTED_KEYS));

describe('sign-registry', () => {
  it('writes a signature of the registry bytes that the library verifies', () => {
    const key = testKey();
    writeKeys([key.public]);

    const result = sign(key.secret);

    expect(result.status).toBe(0);
    expect(result.output).not.toContain(key.secret);
    const signature = read(SIGNATURE);
    expect(signature).toMatch(/^[0-9a-f]{128}\n$/);
    expect(verifyRegistrySignature(REGISTRY_TEXT, signature, [key.public])).toBe(key.public);
    expect(() => verifyRegistrySignature(`${REGISTRY_TEXT} `, signature, [key.public])).toThrow(
      expect.objectContaining({ code: 'SIGNATURE_MISMATCH' })
    );
  });

  it('signs the registry and key list given with --registry and --keys', () => {
    const key = testKey();
    write('other/registry.json', '{"extensions":[],"extractors":[]}');
    writeKeys([key.public], 'other/keys.ts');

    const result = sign(key.secret, ['--registry', 'other/registry.json', '--keys', 'other/keys.ts']);

    expect(result.status).toBe(0);
    expect(
      verifyRegistrySignature('{"extensions":[],"extractors":[]}', read('other/registry.json.sig'), [key.public])
    ).toBe(key.public);
    expect(fs.existsSync(file(SIGNATURE))).toBe(false);
  });

  it('signs with every key given, so apps trusting either key of a rotation verify', () => {
    const [old, next] = [testKey(), testKey()];
    writeKeys([old.public, next.public]);

    expect(sign(`${old.secret} ${next.secret}\n`).status).toBe(0);

    const signature = read(SIGNATURE);
    expect(signature.trim().split('\n')).toHaveLength(2);
    expect(verifyRegistrySignature(REGISTRY_TEXT, signature, [old.public])).toBe(old.public);
    expect(verifyRegistrySignature(REGISTRY_TEXT, signature, [next.public])).toBe(next.public);
  });

  it.each([
    [
      'REGISTRY_SIGNING_KEY is not set',
      () => ({ env: {}, keys: [testKey().public] }),
      /REGISTRY_SIGNING_KEY is not set/,
    ],
    [
      'the key is not hex',
      () => ({ env: { REGISTRY_SIGNING_KEY: 'z'.repeat(64) }, keys: [testKey().public] }),
      /key 1 is not a 64-character hex ed25519 private key/,
    ],
    [
      'the key list is empty',
      () => ({ env: { REGISTRY_SIGNING_KEY: testKey().secret }, keys: [] }),
      /lists no public key; run yarn registry:keygen/,
    ],
    [
      "the key's public key is not listed",
      () => ({ env: { REGISTRY_SIGNING_KEY: testKey().secret }, keys: [testKey().public] }),
      /\(public key [0-9a-f]{64}\) is not listed in/,
    ],
  ])('exits 1 without writing a signature when %s', (_label, setup, message) => {
    const { env, keys }: { env: Record<string, string>; keys: string[] } = setup();
    writeKeys(keys);

    const result = run('sign-registry.js', [], env);

    expect(result.status).toBe(1);
    expect(result.output).toMatch(message);
    if (env.REGISTRY_SIGNING_KEY) expect(result.output).not.toContain(env.REGISTRY_SIGNING_KEY);
    expect(fs.existsSync(file(SIGNATURE))).toBe(false);
  });
});

describe('registry-keygen', () => {
  /** Runs keygen; returns the public key it added and the private key it printed. */
  function keygen() {
    const result = run('registry-keygen.js');
    // On failure, show what keygen said, with any key in it hidden
    if (result.status !== 0) throw new Error(`keygen failed:\n${result.output.replace(/[0-9a-f]{64}/g, '<key>')}`);
    const publicKey = /Added public key ([0-9a-f]{64})/.exec(result.stdout)?.[1];
    const secretKey = /^ {2}([0-9a-f]{64})$/m.exec(result.stdout)?.[1];
    expect(publicKey).toBeDefined();
    expect(secretKey).toBeDefined();
    return { ...result, publicKey: publicKey!, secretKey: secretKey! };
  }

  it('writes only the public key to the key list and never writes the private key to disk', () => {
    const { publicKey, secretKey, stdout } = keygen();

    expect(secretKey).not.toBe(publicKey);
    expect(stdout.split(secretKey)).toHaveLength(2);
    expect(stdout).toMatch(/REGISTRY_SIGNING_KEY in the "registry-signing" environment/);
    expect(support.parseSigningKeys(read(KEYS)).entries.map((entry: { key: string }) => entry.key)).toEqual([
      publicKey,
    ]);
    const secretForms = [secretKey, secretKey.toUpperCase(), Buffer.from(secretKey, 'hex').toString('base64')];
    for (const written of filesUnder(root)) {
      const content = fs.readFileSync(written);
      for (const form of secretForms) expect(content.includes(form)).toBe(false);
      expect(content.includes(Buffer.from(secretKey, 'hex'))).toBe(false);
    }
  });

  it('prints the private key of the public key it adds', () => {
    const { publicKey, secretKey } = keygen();

    expect(sign(secretKey).status).toBe(0);
    expect(verifyRegistrySignature(REGISTRY_TEXT, read(SIGNATURE), [publicKey])).toBe(publicKey);
  });

  it('leaves a key list that compiles, exports the key and is formatted', () => {
    const { publicKey } = keygen();
    const source = read(KEYS);

    const { outputText, diagnostics } = ts.transpileModule(source, {
      compilerOptions: { module: ts.ModuleKind.CommonJS },
      reportDiagnostics: true,
    });
    expect(diagnostics).toEqual([]);
    const exported: { REGISTRY_SIGNING_KEYS?: string[] } = {};
    new Function('exports', outputText)(exported);
    expect(exported.REGISTRY_SIGNING_KEYS).toEqual([publicKey]);

    const prettier = spawnSync(
      process.execPath,
      [require.resolve('prettier/bin/prettier.cjs'), '--config', path.join(REPO, '.prettierrc'), '--check', file(KEYS)],
      { encoding: 'utf8' }
    );
    expect(prettier.stdout + prettier.stderr).not.toMatch(/warn|error/i);
    expect(prettier.status).toBe(0);
  });

  it('keeps the keys already listed when it adds another, for a rotation', () => {
    const first = keygen();
    const second = keygen();

    const { entries } = support.parseSigningKeys(read(KEYS));
    expect(entries.map((entry: { key: string }) => entry.key)).toEqual([first.publicKey, second.publicKey]);
    expect(
      entries.every((entry: { comments: string[] }) => /^\/\/ Added \d{4}-\d{2}-\d{2}$/.test(entry.comments[0]!))
    ).toBe(true);
    expect(second.stdout).toMatch(/next to the 1 key\(s\) already there/);
    expect(second.stdout).toMatch(/REGISTRY_SIGNING_KEY_2/);
  });

  it('refuses a key list it cannot read, before generating a key', () => {
    const unreadable = KEYS_TEMPLATE.replace(KEYS_DECLARATION, '$1[OTHER_KEYS]');
    write(KEYS, unreadable);

    const result = run('registry-keygen.js');

    expect(result.status).toBe(1);
    expect(result.output).toMatch(/can't read OTHER_KEYS/);
    expect(result.output).not.toMatch(/[0-9a-f]{64}/);
    expect(read(KEYS)).toBe(unreadable);
  });
});

describe('the Sign registry workflow', () => {
  const WORKFLOW = fs.readFileSync(path.join(REPO, '.github/workflows/sign-registry.yml'), 'utf8');
  const COMMIT_SUBJECT = 'chore(registry): sign the extension registry';

  /** The `run:` script of the workflow step named `name`. */
  function stepScript(name: string): string {
    const lines = WORKFLOW.split('\n');
    const start = lines.findIndex((line) => line.trim() === `- name: ${name}`);
    const run = lines.findIndex((line, index) => index > start && line.trim() === 'run: |');
    const indent = /^ */.exec(lines[run]!)![0].length + 2;
    const body = lines.slice(run + 1);
    const end = body.findIndex((line) => line.trim() !== '' && /^ */.exec(line)![0].length < indent);
    return (end < 0 ? body : body.slice(0, end)).map((line) => line.slice(indent)).join('\n');
  }

  // Git without the user's config (signing, hooks, default branch), in the throwaway repo
  const gitEnv = { HOME: '/nonexistent', GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null' };
  const git = (cwd: string, ...args: string[]) => {
    const result = spawnSync('git', ['-c', 'user.name=test', '-c', 'user.email=test@example.com', ...args], {
      cwd,
      encoding: 'utf8',
      env: { PATH: process.env.PATH ?? '', ...gitEnv },
    });
    if (result.status !== 0) throw new Error(`git ${args.join(' ')} failed: ${result.stderr}`);
    return result.stdout.trim();
  };
  const signStep = (cwd: string, secret: string) =>
    spawnSync('bash', ['-e', '-c', stepScript('Sign the registry and push the signature')], {
      cwd,
      encoding: 'utf8',
      // The second secret is usually empty: the variable then ends in a space
      env: { PATH: process.env.PATH ?? '', ...gitEnv, REGISTRY_SIGNING_KEY: `${secret} ` },
    });

  it('commits a signature once, re-signs a newer tip when main moved, and never loops', () => {
    const key = testKey();
    writeKeys([key.public]);
    const remote = path.join(root, 'remote.git');
    const work = path.join(root, 'work');
    const other = path.join(root, 'other');
    git(root, 'init', '-q', '--bare', '-b', 'main', remote);
    git(root, 'init', '-q', '-b', 'main', work);
    for (const rel of ['scripts', 'src']) fs.cpSync(file(rel), path.join(work, rel), { recursive: true });
    git(work, 'add', '-A');
    git(work, 'commit', '-q', '-m', 'state');
    git(work, 'remote', 'add', 'origin', remote);
    git(work, 'push', '-q', 'origin', 'main');

    const first = signStep(work, key.secret);
    expect(first.status).toBe(0);
    expect(first.stdout + first.stderr).not.toContain(key.secret);
    expect(git(remote, 'log', '-1', '--format=%s', 'main')).toBe(COMMIT_SUBJECT);
    // Only the signature changes, so the push can't match the workflow's `paths` again
    expect(git(remote, 'diff', '--name-only', 'main~1', 'main')).toBe(SIGNATURE);
    expect(WORKFLOW).not.toMatch(/^\s+- src\/extension-registry\.json\.sig$/m);
    const signature = git(remote, 'show', `main:${SIGNATURE}`);
    expect(verifyRegistrySignature(REGISTRY_TEXT, signature, [key.public])).toBe(key.public);

    // Deterministic signatures: an unchanged registry gives no new commit
    const again = signStep(work, key.secret);
    expect(again.status).toBe(0);
    expect(again.stdout).toContain('already up to date');
    expect(git(remote, 'rev-list', '--count', 'main')).toBe('2');

    // Someone pushes a registry change while the next run still has the older tip checked out
    git(root, 'clone', '-q', remote, other);
    const changed = REGISTRY_TEXT.replace('"extensions"', '"extensions" ');
    fs.writeFileSync(path.join(other, REGISTRY), changed);
    git(other, 'commit', '-q', '-am', 'change the registry');
    git(other, 'push', '-q', 'origin', 'main');
    fs.writeFileSync(path.join(work, REGISTRY), `${REGISTRY_TEXT}\n`);
    git(work, 'commit', '-q', '-am', 'local change that never reaches main');

    const raced = signStep(work, key.secret);
    expect(raced.status).toBe(0);
    expect(raced.stdout).toContain('main moved while signing');
    expect(git(remote, 'log', '-1', '--format=%s', 'main')).toBe(COMMIT_SUBJECT);
    expect(git(remote, 'show', `main:${REGISTRY}`)).toBe(changed.trimEnd());
    const resigned = git(remote, 'show', `main:${SIGNATURE}`);
    expect(verifyRegistrySignature(changed, resigned, [key.public])).toBe(key.public);
  }, 30000);

  it('skips signing with a notice until a signing key secret is stored', () => {
    const check = (keys: string) => {
      const output = file('github-output');
      fs.writeFileSync(output, '');
      const result = spawnSync('bash', ['-e', '-c', stepScript('Check for a signing key')], {
        encoding: 'utf8',
        env: { PATH: process.env.PATH ?? '', SIGNING_KEYS: keys, GITHUB_OUTPUT: output },
      });
      expect(result.status).toBe(0);
      return { stdout: result.stdout, output: fs.readFileSync(output, 'utf8') };
    };

    const missing = check('');
    expect(missing.output).toBe('present=false\n');
    expect(missing.stdout).toMatch(/^::notice title=Registry not signed::No REGISTRY_SIGNING_KEY secret yet/);
    expect(check(testKey().secret)).toEqual({ stdout: '', output: 'present=true\n' });
    expect(WORKFLOW.match(/if: steps\.key\.outputs\.present == 'true'/g)).toHaveLength(3);
  });
});

describe('checkSignature (prepare-registry --check)', () => {
  const check = () => support.checkSignature(root);

  it('notes that there is nothing to check without a key list or keys', () => {
    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/no registry signing key/)] });
    fs.rmSync(file(KEYS));
    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/registry-signing-keys.ts not found/)] });
  });

  it('notes a valid signature', () => {
    const key = testKey();
    writeKeys([key.public]);
    sign(key.secret);

    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/is valid \(signed with key/)] });
  });

  it('only notes a missing, stale or malformed signature, since CI signs after merge', () => {
    const key = testKey();
    writeKeys([key.public]);
    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/\.sig is missing/)] });

    sign(key.secret);
    write(REGISTRY, `${REGISTRY_TEXT}\n`);
    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/doesn't match .* \(stale\)/)] });

    write(SIGNATURE, 'not a signature\n');
    expect(check()).toEqual({ problems: [], notes: [expect.stringMatching(/line 1 is not a 128-character/)] });
  });

  it('reports a malformed key list as a problem', () => {
    write(KEYS, KEYS_TEMPLATE.replace(KEYS_DECLARATION, "$1['abc']"));

    expect(check().problems).toEqual([expect.stringMatching(/signing key 'abc' is not a 64-character/)]);
  });

  it('runs as part of prepare-registry --check', () => {
    write(SCHEMA, fs.readFileSync(path.join(REPO, SCHEMA), 'utf8'));
    write(REGISTRY, '{"extensions":[],"extractors":[]}');
    const key = testKey();
    writeKeys([key.public]);
    sign(key.secret);

    const valid = run('prepare-registry.js', ['--check']);
    expect(valid.status).toBe(0);
    expect(valid.output).toMatch(/extension-registry\.json\.sig is valid/);

    write(KEYS, KEYS_TEMPLATE.replace(KEYS_DECLARATION, "$1['abc']"));
    const broken = run('prepare-registry.js', ['--check']);
    expect(broken.status).toBe(1);
    expect(broken.output).toMatch(/signing key 'abc' is not a 64-character/);
  });
});
